class Solution {
    public boolean strongPasswordCheckerII(String password) {
        if (password.length() < 8) {
            return false;
        }
        boolean lower = false;
        boolean upper = false;
        boolean digit = false;
        boolean special = false;
        String specials = "!@#$%^&*()-+";

        for (int i = 0; i < password.length(); i++) {
            char c = password.charAt(i);
            if (i > 0 && c == password.charAt(i - 1)) {
                return false;
            }
            if (Character.isLowerCase(c)) {
                lower = true;
            } else if (Character.isUpperCase(c)) {
                upper = true;
            } else if (Character.isDigit(c)) {
                digit = true;
            } else if (specials.indexOf(c) >= 0) {
                special = true;
            }
        }

        return lower && upper && digit && special;
    }
}

class Solution {
    public boolean strongPasswordCheckerII(String password) {
        return password.length() >= 8
                && !hasAdjacentDuplicate(password)
                && hasLower(password)
                && hasUpper(password)
                && hasDigit(password)
                && hasSpecial(password);
    }

    private boolean hasAdjacentDuplicate(String password) {
        for (int i = 1; i < password.length(); i++) {
            if (password.charAt(i) == password.charAt(i - 1)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasLower(String s) {
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasUpper(String s) {
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasDigit(String s) {
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasSpecial(String s) {
        String specials = "!@#$%^&*()-+";
        for (char c : s.toCharArray()) {
            if (specials.indexOf(c) >= 0) {
                return true;
            }
        }
        return false;
    }
}

class Solution {
    private static final String SPECIALS = "!@#$%^&*()-+";

    public boolean strongPasswordCheckerII(String password) {
        if (password.length() < 8) {
            return false;
        }
        int mask = 0;
        for (int i = 0; i < password.length(); i++) {
            char c = password.charAt(i);
            if (i > 0 && c == password.charAt(i - 1)) {
                return false;
            }
            mask |= categoryBit(c);
        }
        return mask == 0b1111;
    }

    private int categoryBit(char c) {
        if ('a' <= c && c <= 'z') {
            return 1;
        }
        if ('A' <= c && c <= 'Z') {
            return 2;
        }
        if ('0' <= c && c <= '9') {
            return 4;
        }
        if (SPECIALS.indexOf(c) >= 0) {
            return 8;
        }
        return 0;
    }
}

class Solution {
    private static final String LOWER_PATTERN = ".*[a-z].*";
    private static final String UPPER_PATTERN = ".*[A-Z].*";
    private static final String DIGIT_PATTERN = ".*[0-9].*";
    private static final String SPECIAL_PATTERN = ".*[!@#$%^&*()\\-+].*";

    public boolean strongPasswordCheckerII(String password) {
        return password.length() >= 8
                && password.matches(LOWER_PATTERN)
                && password.matches(UPPER_PATTERN)
                && password.matches(DIGIT_PATTERN)
                && password.matches(SPECIAL_PATTERN)
                && !hasAdjacentDuplicate(password);
    }

    private boolean hasAdjacentDuplicate(String password) {
        for (int i = 1; i < password.length(); i++) {
            if (password.charAt(i) == password.charAt(i - 1)) {
                return true;
            }
        }
        return false;
    }
}
